    await connectionDb();
    const { productId, doBy, quantityToReduce, orderId, reason } = await request.json();

    if (
      !productId ||
      !doBy ||
      quantityToReduce === undefined ||
      quantityToReduce <= 0
    ) {
      return new Response(
        JSON.stringify({
          success: false,
          message:
            "Product ID, user ID, and valid quantity to reduce are required",
        }),
        { status: 400 }
      );
    }

    // Find the stock entry for this product
    const stock = await Stock.findOne({ product: productId });

    if (!stock) {
      return new Response(
        JSON.stringify({
          success: false,
          message: "No stock found for this product",
        }),
        { status: 404 }
      );
    }

    // Check if sufficient stock is available
    if (stock.quantity < quantityToReduce) {
      return new Response(
        JSON.stringify({
          success: false,
          message: "Insufficient stock",
          available: stock.quantity,
          requested: quantityToReduce,
          error: "INSUFFICIENT_STOCK",
        }),
        { status: 400 }
      );
    }
    const existingStock = await Stock.findOne({ product: productId });

