import mongoose from "mongoose";

const StockSchema = new mongoose.Schema(
  {
        product: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Product",
      required: true,
    },
    quantity: {
      type: Number,
      required: true,
      default: 0,
    },
    doBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },
  },
  { timestamps: true },
);

const Stock = mongoose.models.Stock || mongoose.model("Stock", StockSchema);
export default Stock;
